const inp = $input.first().json || {};
const cfg = inp.config || {};
const objectType = String(inp.objectType || 'contacts').toLowerCase();
if (!['contacts','companies','deals'].includes(objectType)) {
  throw new Error(`Unsupported objectType "${objectType}".`);
}

const LASTMOD = { contacts:'lastmodifieddate', companies:'hs_lastmodifieddate', deals:'hs_lastmodifieddate' };

const READ = {
  contacts: ['email','firstname','lastname','phone','mobilephone','company','jobtitle','website',
             'city','state','country','zip','lifecyclestage','createdate','lastmodifieddate',
             'hs_object_id','hs_merged_object_ids','hubspot_owner_id','dedupe_status','dedupe_ignore_pairs','hygiene_score'],
  companies:['name','domain','website','phone','city','state','country','zip','industry',
             'numberofemployees','lifecyclestage','createdate','hs_lastmodifieddate',
             'hs_object_id','hs_merged_object_ids','hubspot_owner_id','dedupe_status','dedupe_ignore_pairs','hygiene_score'],
  deals:    ['dealname','amount','closedate','dealstage','pipeline','createdate',
             'hs_lastmodifieddate','hs_object_id','hs_merged_object_ids','hubspot_owner_id',
             'num_associated_contacts','dedupe_status','dedupe_ignore_pairs','hygiene_score'],
};

const WEIGHTS = {
  contacts:  { email:25, firstname:10, lastname:10, phone:15, company:10, jobtitle:10, country:10, lifecyclestage:10 },
  companies: { name:20, domain:25, phone:10, city:10, country:10, industry:10, numberofemployees:8, website:7 },
  deals:     { dealname:25, amount:25, closedate:25, dealstage:25 },
};

const runId = inp.runId || `manual-${Date.now()}`;
const autoObjects = String(cfg.autoMergeObjects || 'contacts,companies')
  .split(',').map(x => x.trim().toLowerCase()).filter(Boolean);

// Start from a clean accumulator for this run.
const store = $getWorkflowStaticData('global');
store.acc = { key: `${runId}:${objectType}`, records: [] };

return [{ json: {
  runId, objectType,
  accKey: store.acc.key,
  lastModProp: LASTMOD[objectType],
  readProps: READ[objectType],
  weights: WEIGHTS[objectType],
  config: {
    pageSize:           Math.min(Number(cfg.pageSize ?? 100), 100),
    maxPagesPerRun:     Number(cfg.maxPagesPerRun ?? 200),
    maxRecordsForDedup: Number(cfg.maxRecordsForDedup ?? 10000),
    apiThrottleMs:      Number(cfg.apiThrottleMs ?? 250),
    defaultCountry:     String(cfg.defaultCountry || 'US').toUpperCase(),
    dryRun:             cfg.dryRun !== false,
    autoMergeThreshold: Number(cfg.autoMergeThreshold ?? 95),
    reviewThreshold:    Number(cfg.reviewThreshold ?? 72),
    logThreshold:       Number(cfg.logThreshold ?? 55),
    maxMergesPerRun:    Number(cfg.maxMergesPerRun ?? 50),
    maxBlockSize:       Number(cfg.maxBlockSize ?? 60),
    primaryStrategy:    String(cfg.primaryStrategy || 'mostComplete'),
    slackChannel:       cfg.slackChannel || '#crm-hygiene',
    notifyLowConfidence: cfg.notifyLowConfidence !== false,
    canAutoMerge:       autoObjects.includes(objectType),
  },
} }];

// Duplicate detection always does a FULL scan: a duplicate can be an old
// record that has not been modified in years, so a delta window would miss it.
const j = $input.first().json;
const spec = $('⚙️ Resolve Dedup Config').first().json;
const after  = j.nextAfter || null;
const pageNo = Number(j.pageNo || 0) + 1;

const body = {
  limit: spec.config.pageSize,
  properties: spec.readProps,
  sorts: [{ propertyName: spec.lastModProp, direction: 'ASCENDING' }],
  filterGroups: [],
};
if (after) body.after = String(after);

return [{ json: { ...spec, pageNo, after, searchBody: body } }];

const e = $input.first().json || {};
const spec = $('🔁 Next Page Cursor').first().json;
const msg = String(e.error?.message || e.message || JSON.stringify(e)).slice(0, 500);
return [{ json: { ...spec, hasMore: false, aborted: true, abortReason: msg } }];

// Records are pooled in workflow static data rather than passed item-by-item,
// so memory stays flat instead of growing quadratically across pages.
const resp = $input.first().json || {};
const spec = $('🔁 Next Page Cursor').first().json;
const store = $getWorkflowStaticData('global');
if (!store.acc || store.acc.key !== spec.accKey) store.acc = { key: spec.accKey, records: [] };

const cap = spec.config.maxRecordsForDedup;
let capHit = false;
for (const r of (resp.results || [])) {
  if (store.acc.records.length >= cap) { capHit = true; break; }
  store.acc.records.push({ id: r.id, p: r.properties || {}, createdAt: r.createdAt });
}

const nextAfter = resp.paging?.next?.after || null;
return [{ json: {
  ...spec,
  pageNo: spec.pageNo,
  nextAfter,
  collected: store.acc.records.length,
  recordCapHit: capHit,
  hasMore: Boolean(nextAfter) && !capHit,
} }];

