  'II','III','IV','SDR','BDR','AE','CSM','DevOps','API','ERP','CRM','SQL','AWS','GCP']);

const SMALL_WORDS = new Set(['of','and','the','for','in','on','at','to','a','an','or','&','de',
  'da','van','von','der','den','la','le','du','di','el','al','bin','ibn']);

function s(v){ return (v === null || v === undefined) ? '' : String(v).trim(); }
function blank(v){ return s(v) === '' || s(v).toLowerCase() === 'null'; }
function collapse(v){ return s(v).replace(/[\s ]+/g, ' ').trim(); }

// ---- EMAIL ----------------------------------------------------------------
const EMAIL_RE = /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/;

function cleanEmail(raw){
  const out = {clean:'', norm:'', domain:'', local:'', valid:false, flags:[]};
  let e = s(raw).toLowerCase().replace(/[\s​]/g,'').replace(/^mailto:/,'');
  e = e.replace(/^[<("']+/,'').replace(/[>)"'.,;]+$/,'');
  if (!e) return out;
  const at = e.lastIndexOf('@');
  if (at < 1 || at === e.length-1){ out.clean=e; out.flags.push('email_malformed'); return out; }
  let local = e.slice(0,at), domain = e.slice(at+1);
  if (domain.endsWith('.')) domain = domain.slice(0,-1);
  // common typo fixes on the TLD only (conservative)
  const TYPO = {'gmail.co':'gmail.com','gmial.com':'gmail.com','gmai.com':'gmail.com',
    'gmail.con':'gmail.com','hotmial.com':'hotmail.com','yahho.com':'yahoo.com',
    'outlok.com':'outlook.com','hotmail.con':'hotmail.com','yahoo.con':'yahoo.com'};
  if (TYPO[domain]){ out.flags.push('email_typo_fixed:'+domain); domain = TYPO[domain]; }
  out.clean  = local + '@' + domain;
  out.local  = local;
  out.domain = domain;
  out.valid  = EMAIL_RE.test(out.clean) && domain.includes('.');
  if (!out.valid) out.flags.push('email_invalid_syntax');
  // normalised form used ONLY for duplicate matching, never written back
  let nl = local;
  if (domain === 'gmail.com' || domain === 'googlemail.com'){
    nl = nl.split('+')[0].replace(/\./g,'');
  } else {
    nl = nl.split('+')[0];
  }
  out.norm = out.valid ? (nl + '@' + (domain === 'googlemail.com' ? 'gmail.com' : domain)) : '';
  const base = local.split('+')[0].replace(/[._-]/g,'');
  if (ROLE_LOCAL.has(local.split('+')[0]) || ROLE_LOCAL.has(base)) out.flags.push('role_address');
  if (DISPOSABLE.some(d => domain.includes(d))) out.flags.push('disposable_domain');
  if (FREE_MAIL.has(domain)) out.flags.push('free_mail_domain');
  if (/^(test|asdf|qwerty|aaa|xxx|abc|none|na|n\/a|noemail)/.test(local)) out.flags.push('email_looks_fake');
  return out;
}

// ---- PHONE ----------------------------------------------------------------
function cleanPhone(raw, defaultCountry){
  const out = {e164:'', clean:'', valid:false, flags:[]};
  let p = s(raw);
  if (!p) return out;
  const ext = p.match(/(?:ext|x|extension|#)\s*\.?\s*(\d{1,6})\s*$/i);
  if (ext){ out.ext = ext[1]; p = p.slice(0, ext.index); }
  let plus = /^\s*\+/.test(p) || /^\s*00\d/.test(p);
  let digits = p.replace(/\D/g,'');
  if (!digits){ out.flags.push('phone_no_digits'); return out; }
  if (/^00/.test(p.replace(/\D/g,'').slice(0,2)) && /^\s*00/.test(p.trim())){
    digits = digits.replace(/^00/,''); plus = true;
  }
  const cc = DIAL[s(defaultCountry).toUpperCase()] || '';
  if (!plus){
    // national format -> prepend the default country dial code
    if (cc === '1' && digits.length === 11 && digits.startsWith('1')) { /* already 1NXXXXXXXXX */ }
    else if (cc && digits.length <= 11){
      digits = digits.replace(/^0+/, '');            // strip national trunk prefix
      if (!digits.startsWith(cc)) digits = cc + digits;
    } else if (!cc){
      out.flags.push('phone_no_country_context');
    }
  }
  if (digits.length < 8 || digits.length > 15){
    out.flags.push('phone_invalid_length');
    out.clean = '+' + digits;
    return out;
  }
  if (/^(\d)\1+$/.test(digits) || /^(?:0123456789|1234567890)/.test(digits)){
    out.flags.push('phone_looks_fake');
  }
  out.e164  = '+' + digits;
  out.clean = out.e164;
  out.valid = out.flags.length === 0;
  return out;
}

// ---- NAMES / CASING -------------------------------------------------------
function titleCaseWord(w){
  if (!w) return w;
  const upper = w.toUpperCase().replace(/[^A-Z&./]/g,'');
  if (ACRONYMS.has(w.toUpperCase()) || ACRONYMS.has(upper)) return w.toUpperCase();
  if (/\d/.test(w)) return w;                                   // keep 3M, H2O, 24/7
  let t = w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
  t = t.replace(/^(mc)([a-z])/i,  (m,a,b)=> 'Mc' + b.toUpperCase());
  t = t.replace(/^(mac)([a-z]{2})/i,(m,a,b)=> 'Mac'+ b.charAt(0).toUpperCase()+b.slice(1));
  t = t.replace(/^(o')([a-z])/i,  (m,a,b)=> "O'" + b.toUpperCase());
  t = t.replace(/^(d')([a-z])/i,  (m,a,b)=> "d'" + b.toUpperCase());
  t = t.replace(/-([a-z])/g,      (m,b)  => '-'  + b.toUpperCase());
  return t;
}

function smartCase(raw, opts){
  const o = opts || {};
  let v = collapse(raw);
  if (!v) return '';
  const words = v.split(' ');
  // Re-case only when at least one word is clearly wrong (fully upper or fully
  // lower). Deliberate casing like "Jean-Luc Picard" or "DeShawn" is preserved.
  const anomalous = words.some(word => {
    const letters = word.replace(/[^A-Za-z]/g, '');
    if (letters.length < 2) return false;
    if (ACRONYMS.has(word.toUpperCase())) return false;
    return letters === letters.toUpperCase() || letters === letters.toLowerCase();
  });
  if (!o.force && !anomalous) return v;
  return words.map((w,i) => {
    const lw = w.toLowerCase();
    if (i > 0 && SMALL_WORDS.has(lw) && !o.keepSmall) return lw;
    return titleCaseWord(w);
  }).join(' ');
}

function cleanPersonName(raw){
  let v = collapse(raw).replace(/[",;]+/g,' ').replace(/\s+/g,' ').trim();
  v = v.replace(/^(mr|mrs|ms|miss|dr|prof|eng|sir)\.?\s+/i, '');
  if (!v) return {clean:'', flags:[]};
  const flags = [];
  if (/^[^A-Za-zÀ-ɏ؀-ۿ]+$/.test(v)) flags.push('name_not_alphabetic');
  if (/(test|asdf|qwerty|unknown|n\/a|none|xxx)/i.test(v) && v.length <= 8) flags.push('name_looks_fake');
  if (/https?:\/\/|www\.|@/.test(v)) flags.push('name_contains_url_or_email');
  return {clean: smartCase(v), flags};
}

// ---- COMPANY --------------------------------------------------------------
function normCompany(raw){
  let v = collapse(raw).toLowerCase();
  if (!v) return '';
  v = v.replace(/[‘’“”]/g,"'").replace(/&/g,' and ');
  v = v.replace(/[.,;:()\[\]\/\\'"`]/g,' ').replace(/\s+/g,' ').trim();
  let toks = v.split(' ').filter(Boolean);
  // Strip TRAILING legal forms only. Stripping them anywhere would turn
  // "Corporation Technologies Ltd" into "technologies".
  while (toks.length > 1 && LEGAL_SUFFIX.has(toks[toks.length-1])) toks.pop();
  return toks.join(' ').trim();
}

function cleanCompanyName(raw){
  const v = collapse(raw).replace(/[",;]+$/,'').trim();
  if (!v) return {clean:'', flags:[]};
  const flags = [];
  if (/^(unknown|n\/a|none|test|asdf|-{1,})$/i.test(v)) flags.push('company_looks_fake');
  return {clean: smartCase(v, {keepSmall:false}), flags};
}

function normDomain(raw){
  let d = s(raw).toLowerCase().trim();
  if (!d) return '';
  d = d.replace(/^https?:\/\//,'').replace(/^www\d?\./,'').split('/')[0].split('?')[0]
       .split('#')[0].split(':')[0].replace(/\.$/,'');
  if (!d.includes('.') || /\s/.test(d)) return '';
  return d;
}

// ---- GEO ------------------------------------------------------------------
function normCountry(raw){
  const v = collapse(raw);
  if (!v) return {clean:'', iso:'', flags:[]};
  const k = v.toLowerCase().replace(/\./g,'').trim();
  if (/^[A-Za-z]{2}$/.test(v) && Object.values(COUNTRY).includes(v.toUpperCase()))
    return {clean:v.toUpperCase(), iso:v.toUpperCase(), flags:[]};
  const iso = COUNTRY[k] || COUNTRY[k.replace(/^the /,'')] || '';
  if (!iso) return {clean:v, iso:'', flags:['country_unmapped']};
  return {clean:iso, iso, flags:[]};
}

function normState(raw, iso){
  const v = collapse(raw);
  if (!v) return {clean:'', flags:[]};
  if (iso !== 'US' && iso !== 'CA') return {clean:v, flags:[]};
  if (/^[A-Za-z]{2}$/.test(v)) return {clean:v.toUpperCase(), flags:[]};
  const code = US_STATE[v.toLowerCase()];
  return code ? {clean:code, flags:[]} : {clean:v, flags:['state_unmapped']};
}

// ---- SCORING --------------------------------------------------------------
function completeness(props, weights){
  let got = 0, total = 0;
  const missing = [];
  for (const [f, w] of Object.entries(weights)){
    total += w;
    if (!blank(props[f])) got += w; else missing.push(f);
  }
  return {score: total ? Math.round((got/total)*100) : 0, missing};
}

function pick(obj, keys){ const o = {}; for (const k of keys) if (k in obj) o[k] = obj[k]; return o; }
function uniq(a){ return Array.from(new Set(a.filter(Boolean))); }
function dayDiff(a, b){
  const x = Date.parse(a), y = Date.parse(b);
  if (isNaN(x) || isNaN(y)) return null;
  return Math.abs(x - y) / 86400000;
}
// ============================ END LIB =======================================

// ===========================================================================
//  CLUSTER & SCORE  —  blocking keys → candidate pairs → confidence score
//  → union-find on high-confidence links → primary selection → tiering.
// ===========================================================================
const spec  = $input.first().json;
const cfg   = spec.config;
const type  = spec.objectType;
const store = $getWorkflowStaticData('global');
const recs  = (store.acc && store.acc.key === spec.accKey) ? store.acc.records : [];
store.acc = { key: null, records: [] };          // release memory immediately

const notes = [];
if (spec.recordCapHit) notes.push(`Record cap ${cfg.maxRecordsForDedup} reached — scan truncated.`);
if (spec.aborted)      notes.push(`Scan aborted: ${spec.abortReason}`);

// ---------------------------------------------------------------- KEYS ----
const byId = new Map();
for (const r of recs) {
  const p = r.p || {};
  const k = { id: r.id, p, createdAt: r.createdAt || p.createdate, keys: [], meta: {} };

  if (type === 'contacts') {
    const em = cleanEmail(p.email);
    const ph = cleanPhone(p.phone || p.mobilephone, normCountry(p.country).iso || cfg.defaultCountry);
    const fn = collapse(p.firstname).toLowerCase().replace(/[^a-zÀ-ɏ\s-]/g, '');
    const ln = collapse(p.lastname).toLowerCase().replace(/[^a-zÀ-ɏ\s-]/g, '');
    const comp = normCompany(p.company);
    k.meta = { email: em.norm, domain: em.domain, free: FREE_MAIL.has(em.domain),
               role: em.flags.includes('role_address'), phone: ph.e164, fn, ln, comp,
               country: normCountry(p.country).iso };
    if (em.norm)               k.keys.push('E|' + em.norm);
    if (ph.e164 && ln)         k.keys.push('P|' + ph.e164);
    if (fn && ln)              k.keys.push('N|' + fn + '|' + ln);
    if (ln && em.domain && !k.meta.free) k.keys.push('D|' + ln + '|' + em.domain);
    if (ln && comp)            k.keys.push('C|' + ln + '|' + comp);
  }

  if (type === 'companies') {
    const dom  = normDomain(p.domain || p.website);
    const name = normCompany(p.name);
    const toks = name.split(' ').filter(Boolean).sort().join(' ');
    k.meta = { domain: dom, name, toks, city: collapse(p.city).toLowerCase(),
               country: normCountry(p.country).iso, phone: cleanPhone(p.phone, normCountry(p.country).iso || cfg.defaultCountry).e164 };
    if (dom)  k.keys.push('E|' + dom);
    if (name) k.keys.push('N|' + name);
    if (toks) k.keys.push('T|' + toks);
    if (k.meta.phone) k.keys.push('P|' + k.meta.phone);
  }

  if (type === 'deals') {
    const dn = normCompany(p.dealname);                 // same tokeniser works fine
    const amt = Number(String(p.amount || '').replace(/[^0-9.\-]/g, ''));
    const close = s(p.closedate).slice(0, 10);
    k.meta = { dn, amt: isNaN(amt) ? null : Math.round(amt * 100) / 100, close,
               pipeline: s(p.pipeline), stage: s(p.dealstage),
               contacts: Number(p.num_associated_contacts || 0) };
    if (dn) k.keys.push('N|' + dn);
    if (k.meta.amt !== null && close) k.keys.push('A|' + k.meta.amt + '|' + close);
  }

  byId.set(r.id, k);
}

// --------------------------------------------------------- BLOCKING -------
const blocks = new Map();
for (const k of byId.values()) for (const key of uniq(k.keys)) {
  if (!blocks.has(key)) blocks.set(key, []);
  blocks.get(key).push(k.id);
}

let oversized = 0;
const candidate = new Map();        // "a|b" -> Set(keyPrefixes)
for (const [key, ids] of blocks) {
  if (ids.length < 2) continue;
  if (ids.length > cfg.maxBlockSize) { oversized++; continue; }   // e.g. 300 blank-name records
  for (let i = 0; i < ids.length; i++) for (let j = i + 1; j < ids.length; j++) {
    const a = ids[i] < ids[j] ? ids[i] : ids[j];
    const b = ids[i] < ids[j] ? ids[j] : ids[i];
    const pk = a + '|' + b;
    if (!candidate.has(pk)) candidate.set(pk, new Set());
    candidate.get(pk).add(key[0]);
  }
}
if (oversized) notes.push(`${oversized} blocking key(s) exceeded ${cfg.maxBlockSize} members and were skipped (usually blank or placeholder values).`);

// ---------------------------------------------------------- SCORING ------
function scoreContacts(a, b) {
  const A = a.meta, B = b.meta; const why = []; let sc = 0;
  let usedDomain = false, usedPhone = false;
  if (A.email && A.email === B.email) { sc = 100; why.push('identical normalised email'); }
  else if (A.phone && A.phone === B.phone && A.ln && A.ln === B.ln) { sc = 90; usedPhone = true; why.push('same phone (E.164) + same last name'); }
  else if (A.fn && A.fn === B.fn && A.ln && A.ln === B.ln && A.domain && A.domain === B.domain && !A.free) { sc = 88; usedDomain = true; why.push('same full name + same corporate email domain'); }
  else if (A.fn && A.fn === B.fn && A.ln && A.ln === B.ln && A.comp && A.comp === B.comp) { sc = 80; why.push('same full name + same company'); }
  else if (A.fn && B.fn && A.fn[0] === B.fn[0] && A.ln && A.ln === B.ln && A.domain && A.domain === B.domain && !A.free) { sc = 72; usedDomain = true; why.push('first initial + last name + same corporate domain'); }
  else if (A.ln && A.ln === B.ln && A.comp && A.comp === B.comp) { sc = 58; why.push('same last name + same company'); }
  else if (A.fn && A.fn === B.fn && A.ln && A.ln === B.ln) { sc = 56; why.push('same full name only'); }
  if (sc < 100) {
    if (A.role || B.role) { sc -= 30; why.push('penalty: role/shared mailbox address'); }
    // Only penalise differing emails when the match did NOT already come from
    // the email domain — two addresses on the same corporate domain differing
    // is the expected shape of that duplicate, not evidence against it.
    if (!usedDomain && A.email && B.email && A.email !== B.email) { sc -= 5; why.push('penalty: different email addresses'); }
    if (A.country && B.country && A.country !== B.country) { sc -= 8; why.push('penalty: different countries'); }
    if (!usedPhone && A.phone && B.phone && A.phone === B.phone && sc > 0) { sc += 4; why.push('bonus: phone also matches'); }
    sc = Math.min(sc, 94);
  }
  return { sc: Math.max(0, Math.round(sc)), why };
}

function scoreCompanies(a, b) {
  const A = a.meta, B = b.meta; const why = []; let sc = 0;
  if (A.domain && A.domain === B.domain) { sc = 100; why.push('identical web domain'); }
  else if (A.name && A.name === B.name && A.country && A.country === B.country) { sc = 88; why.push('same legal-suffix-stripped name + same country'); }
  else if (A.name && A.name === B.name) { sc = 74; why.push('same legal-suffix-stripped name'); }
  else if (A.toks && A.toks === B.toks && A.city && A.city === B.city) { sc = 68; why.push('same name tokens + same city'); }
  else if (A.phone && A.phone === B.phone) { sc = 62; why.push('same phone number'); }
  if (sc < 100 && A.domain && B.domain && A.domain !== B.domain) {
    sc = Math.min(sc, 40);
    why.push('penalty: both have domains and they differ — almost never the same company');
  }
  if (sc < 100) sc = Math.min(sc, 94);
  return { sc: Math.max(0, Math.round(sc)), why };
}

function scoreDeals(a, b) {
  const A = a.meta, B = b.meta; const why = []; let sc = 0;
  const dd = (A.close && B.close) ? dayDiff(A.close, B.close) : null;
  const sameAmt = A.amt !== null && A.amt === B.amt;
  if (A.dn && A.dn === B.dn && sameAmt && dd !== null && dd <= 30) { sc = 84; why.push('same deal name + same amount + close dates within 30 days'); }
  else if (A.dn && A.dn === B.dn && dd !== null && dd <= 7) { sc = 74; why.push('same deal name + close dates within 7 days'); }
  else if (A.dn && A.dn === B.dn && A.pipeline === B.pipeline) { sc = 62; why.push('same deal name + same pipeline'); }
  else if (sameAmt && A.close && A.close === B.close && A.pipeline === B.pipeline) { sc = 58; why.push('same amount + same close date + same pipeline'); }
  if (A.stage && B.stage && A.stage !== B.stage) { sc -= 6; why.push('penalty: different deal stages'); }
  // Deals are never auto-merged — a human always confirms the company link.
  return { sc: Math.max(0, Math.min(Math.round(sc), 94)), why };
}

const scorer = { contacts: scoreContacts, companies: scoreCompanies, deals: scoreDeals }[type];

const scored = [];
for (const pk of candidate.keys()) {
  const [ai, bi] = pk.split('|');
  const a = byId.get(ai), b = byId.get(bi);
  if (!a || !b) continue;
  // Client opt-out: either record flagged do_not_merge removes the pair entirely.
  if (s(a.p.dedupe_status) === 'do_not_merge' || s(b.p.dedupe_status) === 'do_not_merge') continue;
  // Already merged into one another in a previous run.
  const am = s(a.p.hs_merged_object_ids).split(';').map(x => x.trim());
  const bm = s(b.p.hs_merged_object_ids).split(';').map(x => x.trim());
  if (am.includes(b.id) || bm.includes(a.id)) continue;
  // A human already said "not a duplicate" for exactly this pair — never ask twice.
  const aIgn = s(a.p.dedupe_ignore_pairs).split(/[;,\s]+/).map(x => x.trim());
  const bIgn = s(b.p.dedupe_ignore_pairs).split(/[;,\s]+/).map(x => x.trim());
  if (aIgn.includes(b.id) || bIgn.includes(a.id)) continue;
  const { sc, why } = scorer(a, b);
  if (sc < cfg.logThreshold) continue;
  scored.push({ a, b, score: sc, why });
}
scored.sort((x, y) => y.score - x.score);

// ------------------------------------------------- PRIMARY SELECTION -----
function primaryOf(a, b) {
  const ca = completeness(a.p, spec.weights).score;
  const cb = completeness(b.p, spec.weights).score;
  const ta = Date.parse(a.createdAt || a.p.createdate || 0) || 0;
  const tb = Date.parse(b.createdAt || b.p.createdate || 0) || 0;
  let winner;
  if (cfg.primaryStrategy === 'oldest')      winner = ta <= tb ? a : b;
  else if (cfg.primaryStrategy === 'newest') winner = ta >= tb ? a : b;
  else {                                        // mostComplete (default)
    if (ca !== cb) winner = ca > cb ? a : b;
    else if (ta !== tb) winner = ta < tb ? a : b;      // tie → keep the original
    else winner = Number(a.id) <= Number(b.id) ? a : b;
  }
  const loser = winner === a ? b : a;
  return { primary: winner, secondary: loser, compPrimary: winner === a ? ca : cb,
           compSecondary: winner === a ? cb : ca };
}

// --------------- UNION-FIND on exact matches only (transitive-safe) ------
const parent = new Map();
const find = x => { while (parent.get(x) !== x) { parent.set(x, parent.get(parent.get(x))); x = parent.get(x); } return x; };
const union = (x, y) => { const rx = find(x), ry = find(y); if (rx !== ry) parent.set(rx, ry); };
for (const id of byId.keys()) parent.set(id, id);
const exact = scored.filter(p => p.score >= cfg.autoMergeThreshold);
for (const p of exact) union(p.a.id, p.b.id);

const clusters = new Map();
for (const p of exact) {
  const root = find(p.a.id);
  if (!clusters.has(root)) clusters.set(root, new Set());
  clusters.get(root).add(p.a.id); clusters.get(root).add(p.b.id);
}

const ops = [];
const consumed = new Set();
for (const [, set] of clusters) {
  const members = Array.from(set).map(id => byId.get(id)).filter(Boolean);
  if (members.length < 2) continue;
  // Elect one survivor for the whole cluster, then merge every other member in.
  let champion = members[0];
  for (let i = 1; i < members.length; i++) champion = primaryOf(champion, members[i]).primary;
  for (const m of members) {
    if (m.id === champion.id) continue;
    const key = [champion.id, m.id].sort().join('|');
    consumed.add(key);
    const why = (scored.find(p => [p.a.id, p.b.id].sort().join('|') === key) || {}).why || ['exact-match cluster'];
    ops.push({ tier: 'auto', score: 100, primary: champion, secondary: m, why,
               clusterSize: members.length });
  }
}

for (const p of scored) {
  const key = [p.a.id, p.b.id].sort().join('|');
  if (consumed.has(key)) continue;
  if (p.score >= cfg.autoMergeThreshold) continue;   // already handled by a cluster
  consumed.add(key);
  const sel = primaryOf(p.a, p.b);
  ops.push({ tier: p.score >= cfg.reviewThreshold ? 'review' : 'log',
             score: p.score, primary: sel.primary, secondary: sel.secondary, why: p.why,
             clusterSize: 2 });
}

// -------------------------------------------- POLICY GATES / KILL SWITCH --
let autoUsed = 0;
for (const op of ops) {
  if (op.tier !== 'auto') continue;
  if (!cfg.canAutoMerge) { op.tier = 'review'; op.why = [...op.why, `policy: ${type} are never auto-merged`]; continue; }
  if (autoUsed >= cfg.maxMergesPerRun) {
    op.tier = 'deferred';
    op.why = [...op.why, `deferred: maxMergesPerRun (${cfg.maxMergesPerRun}) reached — will merge on the next run`];
    continue;
  }
  autoUsed++;
}

// -------------------------------------------------------- OUTPUT ---------
const LABEL = { contacts: p => `${s(p.firstname)} ${s(p.lastname)}`.trim() || s(p.email) || 'contact',
                companies: p => s(p.name) || s(p.domain) || 'company',
                deals: p => s(p.dealname) || 'deal' };
const PORTAL = { contacts: 'contact', companies: 'company', deals: 'deal' };

const orphanDeals = type === 'deals'
  ? recs.filter(r => Number(r.p.num_associated_contacts || 0) === 0).map(r => r.id) : [];

const tally = { auto:0, review:0, log:0, deferred:0 };
const out = ops.map((op, i) => {
  tally[op.tier] = (tally[op.tier] || 0) + 1;
  return { json: {
    isPair: true, seq: i + 1, runId: spec.runId, objectType: type, tier: op.tier,
    score: op.score, reasons: op.why, clusterSize: op.clusterSize,
    dryRun: cfg.dryRun,
    primaryId: op.primary.id, secondaryId: op.secondary.id,
    primaryLabel: LABEL[type](op.primary.p), secondaryLabel: LABEL[type](op.secondary.p),
    primaryCreated: op.primary.createdAt || op.primary.p.createdate,
    secondaryCreated: op.secondary.createdAt || op.secondary.p.createdate,
    primaryScore: completeness(op.primary.p, spec.weights).score,
    secondaryScore: completeness(op.secondary.p, spec.weights).score,
    primaryIgnore: s(op.primary.p.dedupe_ignore_pairs),
    secondaryIgnore: s(op.secondary.p.dedupe_ignore_pairs),
    primaryUrl: `https://app.hubspot.com/contacts/0/${PORTAL[type]}/${op.primary.id}`,
    secondaryUrl: `https://app.hubspot.com/contacts/0/${PORTAL[type]}/${op.secondary.id}`,
    matchKeys: type === 'contacts'
      ? { email: op.primary.meta.email, phone: op.primary.meta.phone, name: `${op.primary.meta.fn} ${op.primary.meta.ln}`.trim() }
      : type === 'companies'
      ? { domain: op.primary.meta.domain, name: op.primary.meta.name }
      : { dealname: op.primary.meta.dn, amount: op.primary.meta.amt, closedate: op.primary.meta.close },
    config: cfg,
    scanStats: { scanned: recs.length, pairsFound: ops.length, tally, notes, orphanDeals },
  } };
});

// Always emit at least one item so the loop that follows never starves.
if (!out.length) {
  return [{ json: { isPair: false, runId: spec.runId, objectType: type, dryRun: cfg.dryRun,
                    config: cfg,
                    scanStats: { scanned: recs.length, pairsFound: 0,
                                 tally: { auto:0, review:0, log:0, deferred:0 },
                                 notes, orphanDeals } } }];
}
return out;

const rows  = $input.all().map(i => i.json).filter(r => r.isPair !== false);
const stats = $('🔍 Cluster & Score Duplicates').first().json.scanStats || {};
const cfg   = $('⚙️ Resolve Dedup Config').first().json;
const type  = cfg.objectType;

const count = o => rows.filter(r => r.outcome === o).length;
const tier  = t => rows.filter(r => r.tier === t).length;

const top = rows.filter(r => r.tier === 'log' || r.tier === 'deferred')
  .sort((a, b) => b.score - a.score).slice(0, 10)
  .map(r => `• \`${r.score}\` <${r.primaryUrl}|${r.primaryLabel}> ⟷ <${r.secondaryUrl}|${r.secondaryLabel}> — ${(r.reasons || [])[0] || ''}`);

const lines = [
  `*:mag: Duplicate scan — ${type}*  ${cfg.config.dryRun ? '(dry run)' : ''}`,
  `Scanned *${stats.scanned || 0}* records · found *${stats.pairsFound || 0}* duplicate pair(s)`,
  `:zap: auto-merged *${tier('auto')}* · :raising_hand: awaiting approval *${tier('review')}* · :hourglass: deferred *${tier('deferred')}* · :memo: logged *${tier('log')}*`,
  count('failed') ? `:warning: *${count('failed')}* pair(s) failed — see the execution log.` : '',
  (stats.orphanDeals || []).length ? `:link: *${stats.orphanDeals.length}* deal(s) have no associated contact.` : '',
  ...(stats.notes || []).map(n => `:information_source: ${n}`),
  top.length ? '\n*Top pairs left for a human:*' : '',
  ...top,
].filter(Boolean);

return [{ json: {
  ok: true, runId: cfg.runId, kind: 'dedup', objectType: type,
  reportText: lines.join('\n'),
  shouldNotify: cfg.config.notifyLowConfidence && (stats.pairsFound || 0) > 0,
  summary: {
    scanned:     stats.scanned || 0,
    pairsFound:  stats.pairsFound || 0,
    autoQueued:  tier('auto'),
    reviewQueued: tier('review'),
    deferred:    tier('deferred'),
    loggedOnly:  tier('log'),
    failed:      count('failed'),
    orphanDeals: (stats.orphanDeals || []).length,
    dryRun:      cfg.config.dryRun,
    notes:       stats.notes || [],
  },
} }];

const j = $('📊 Summarize Dedup Run').first().json;
return [{ json: { ok: true, runId: j.runId, kind: 'dedup',
                  objectType: j.objectType, summary: j.summary } }];
